krb5_boolean /* <=== krb5_match_config_pattern */ 
krb5_match_config_pattern(const char *string, const char *pattern)
{
    const char *ptr;
    char next = '\0';
    int len = strlen(pattern);

    for (ptr = strstr(string,pattern); ptr != 0; ptr = strstr(ptr+len,pattern)) {
        if (ptr == string
            || isspace((unsigned char)*(ptr-1))
            || *(ptr-1) ==',') {
            next = *(ptr + len);
            if (next == '\0' || isspace((unsigned char)next) || next ==',') {
                return TRUE;
            }
        }
    }
    return FALSE;
}

static krb5_error_code /* <=== krb5int_build_principal_va */ 
krb5int_build_principal_va(krb5_context context,
                           krb5_principal princ,
                           unsigned int rlen,
                           const char *realm,
                           const char *first,
                           va_list ap)
{
    krb5_error_code retval = 0;
    char *r = NULL;
    krb5_data *data = NULL;
    krb5_int32 count = 0;
    krb5_int32 size = 2;  /* initial guess at needed space */
    char *component = NULL;

    data = malloc(size * sizeof(krb5_data));
    if (!data) { retval = ENOMEM; }

    if (!retval) {
        r = strdup(realm);
        if (!r) { retval = ENOMEM; }
    }

    if (!retval && first) {
        data[0].length = strlen(first);
        data[0].data = strdup(first);
        if (!data[0].data) { retval = ENOMEM; }
        count++;

        /* ap is only valid if first is non-NULL */
        while (!retval && (component = va_arg(ap, char *))) {
            if (count == size) {
                krb5_data *new_data = NULL;

                size *= 2;
                new_data = realloc ((char *) data, sizeof(krb5_data) * size);
                if (new_data) {
                    data = new_data;
                } else {
                    retval = ENOMEM;
                }
            }

            if (!retval) {
                data[count].length = strlen(component);
                data[count].data = strdup(component);
                if (!data[count].data) { retval = ENOMEM; }
                count++;
            }
        }
    }

    if (!retval) {
        princ->type = KRB5_NT_UNKNOWN;
        princ->magic = KV5M_PRINCIPAL;
        krb5_princ_set_realm_data(context, princ, r);
        krb5_princ_set_realm_length(context, princ, rlen);
        princ->data = data;
        princ->length = count;
        r = NULL;    /* take ownership */
        data = NULL; /* take ownership */
    }

    if (data) {
        while (--count >= 0) {
            free(data[count].data);
        }
        free(data);
    }
    free(r);

    return retval;
}

krb5_error_code KRB5_CALLCONV_C /* <=== krb5_build_principal */ 
krb5_build_principal(krb5_context context,
                     krb5_principal * princ,
                     unsigned int rlen,
                     const char * realm, ...)
{
    krb5_error_code retval = 0;
    va_list ap;

    va_start(ap, realm);
    retval = krb5_build_principal_alloc_va(context, princ, rlen, realm, ap);
    va_end(ap);

    return retval;
}

krb5_error_code KRB5_CALLCONV /* <=== krb5_build_principal_alloc_va */ 
krb5_build_principal_alloc_va(krb5_context context,
                              krb5_principal *princ,
                              unsigned int rlen,
                              const char *realm,
                              va_list ap)
{
    krb5_error_code retval = 0;
    krb5_principal p;
    char *first;

    p = malloc(sizeof(krb5_principal_data));
    if (p == NULL)
        return ENOMEM;

    first = va_arg(ap, char *);
    retval = krb5int_build_principal_va(context, p, rlen, realm, first, ap);
    if (retval) {
        free(p);
        return retval;
    }

    *princ = p;
    return 0;
}

void /* <=== kdc_err */ 
kdc_err(krb5_context call_context, errcode_t code, const char *fmt, ...)
{
    va_list ap;

    if (call_context)
        krb5_copy_error_message(kdc_err_context, call_context);
    va_start(ap, fmt);
    com_err_va(kdc_progname, code, fmt, ap);
    va_end(ap);
}

krb5_error_code /* <=== krb5int_get_domain_realm_mapping */ 
krb5int_get_domain_realm_mapping(krb5_context context,
                                 const char *host, char ***realmsp)
{
    char **retrealms;
    char *realm, *cp, *temp_realm;
    krb5_error_code retval;
    char temp_host[MAX_DNS_NAMELEN+1];

    /* do sanity check and lower-case */
    retval = krb5int_clean_hostname(context, host, temp_host, sizeof temp_host);
    if (retval)
        return retval;
    /*
      Search for the best match for the host or domain.
      Example: Given a host a.b.c.d, try to match on:
      1) a.b.c.d  2) .b.c.d.   3) b.c.d  4)  .c.d  5) c.d  6) .d   7) d
    */

    cp = temp_host;
    realm = (char *)NULL;
    temp_realm = 0;
    while (cp ) {
        retval = profile_get_string(context->profile, KRB5_CONF_DOMAIN_REALM, cp,
                                    0, (char *)NULL, &temp_realm);
        if (retval)
            return retval;
        if (temp_realm != (char *)NULL)
            break;        /* Match found */

        /* Setup for another test */
        if (*cp == '.') {
            cp++;
        } else {
            cp = strchr(cp, '.');
        }
    }
    if (temp_realm != (char*)NULL) {
        realm = strdup(temp_realm);
        profile_release_string(temp_realm);
        if (!realm) {
            return ENOMEM;
        }
    }
    retrealms = (char **)calloc(2, sizeof(*retrealms));
    if (!retrealms) {
        if (realm != (char *)NULL)
            free(realm);
        return ENOMEM;
    }

    retrealms[0] = realm;
    retrealms[1] = 0;

    *realmsp = retrealms;
    return 0;
}

